mapper.update:
update sys_dict_data
set dict_value = dict_value + 1
where dict_type = #{dictType}
  and dict_label = #{dictLabel}

update sys_dict_data
set dict_value = dict_value - 1
where dict_type = #{dictType}
  and dict_label = #{dictLabel}
  and dict_value > 0

mapper.select:
select dict_value
from sys_dict_data
where dict_type = #{dictType}
  and dict_label = #{dictLabel}
limit 1
